 void CheckOptionalBindings(){string file=Storage.PathOf("settings.json"),original=File.ReadAllText(file);var before=Clone(settings);try{autoReturn.Checked=!before.AutoReturn;allowSleep.Checked=!before.AllowSleep;gameProfilesEnabled.Checked=!before.GameProfilesEnabled;for(int i=0;i<3;i++)actionEnabled[i].Checked=false;Save();var saved=Storage.Read<Settings>("settings.json");if(saved.AutoReturn==before.AutoReturn||saved.AllowSleep==before.AllowSleep||saved.GameProfilesEnabled==before.GameProfilesEnabled||saved.ControllerActions.Any(a=>a.Enabled))throw new Exception("Optional settings did not persist");}finally{File.WriteAllText(file,original);settings=before;autoReturn.Checked=before.AutoReturn;allowSleep.Checked=before.AllowSleep;gameProfilesEnabled.Checked=before.GameProfilesEnabled;for(int i=0;i<3;i++){var b=before.ControllerActions[i];actionEnabled[i].Checked=b.Enabled;actionChord[i].SelectedItem=actionChord[i].Items.Cast<Choice>().First(c=>c.Id==b.Mask.ToString());actionType[i].SelectedItem=actionType[i].Items.Cast<Choice>().First(c=>c.Id==b.Action);}UpdateMode();}}
