  if(!settings.AutoReturn||!saved.LauncherStarted||saved.Launcher=="Xbox")return;bool open=saved.Launcher=="Playnite"?PlayniteClient.Running:SteamClient.IsBigPictureOpen();if(open){sawLauncher=true;launcherClosed=null;launcherRoots.UnionWith(GameActivity.LauncherIds());return;}if(!sawLauncher)return;bool gameRunning=await Task.Run(()=>GameActivity.Any(launcherRoots));if(gameRunning){launcherClosed=null;return;}if(!launcherClosed.HasValue)launcherClosed=DateTime.UtcNow;if(OptionalPolicy.AutoReturnEligible(settings.AutoReturn,engine.Active,sawLauncher,open,busy||OwnedForms.Length>0,gameRunning,launcherClosed,DateTime.UtcNow))await Work(()=>engine.Restore(settings.TimeoutSeconds),true);
 }
